from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class File_upload(EmssimCommand):
    def __init__(self, method="file_upload", timeout=60, rpc_connection_name='localRPC'):
        super(File_upload, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(File_upload, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "File stored at following path"):
                self._ret['folder_path'] = data["path"]
            elif (data["msg"] == "Cannot create PM stats folder"):
                self._ret['folder_path'] = None
            elif ("status" in data):
                self._ret["status"] = data["status"]
        elif ("status" in data):
            self._ret["status"] = data["status"]
